"""Weight conversion helpers for logistics."""

from decimal import Decimal, InvalidOperation

KG_PER_GRAM = Decimal("1000")
KG_PER_POUND = Decimal("0.45359237")


def to_decimal(value):
    """Return value as a finite Decimal."""
    if isinstance(value, bool):
        raise TypeError("weight must not be boolean")
    try:
        result = Decimal(str(value))
    except (InvalidOperation, ValueError) as error:
        raise ValueError("weight must be numeric") from error
    if not result.is_finite():
        raise ValueError("weight must be finite")
    return result


def normalize_unit(unit):
    """Return a lower-case unit name after checking it is text."""
    if not isinstance(unit, str):
        raise TypeError("unit must be a string")
    normalized = unit.strip().lower()
    if normalized not in {"g", "kg", "lb"}:
        raise ValueError("unit must be g, kg or lb")
    return normalized


def to_kilograms(value, unit):
    """Return a weight in kilograms."""
    amount = to_decimal(value)
    if amount < 0:
        raise ValueError("weight must be non-negative")
    normalized = normalize_unit(unit)
    if normalized == "kg":
        return amount
    if normalized == "g":
        return amount
    return amount * KG_PER_POUND


def to_grams(value, unit):
    """Return a weight in grams."""
    return to_kilograms(value, unit) * KG_PER_GRAM


def format_weight(value, unit="kg"):
    """Return a weight with three fractional digits."""
    amount = to_kilograms(value, unit)
    return f"{amount:.3f} kg"

"""Shipping fee calculation."""

from .parcels import parse_parcel
from .rates import rate_breakdown


def shipping_fee(parcel):
    """Return the shipping fee for one parcel."""
    parsed = parse_parcel(parcel)
    breakdown = rate_breakdown(
        parsed["weight_kg"], parsed["zone"], parsed["express"]
    )
    return breakdown["total"]


def quote_summary(parcel):
    """Return a short quote line for one parcel."""
    parsed = parse_parcel(parcel)
    fee = shipping_fee(parcel)
    service = "express" if parsed["express"] else "standard"
    return (
        f"{parsed['id']}: {parsed['zone']} "
        f"{parsed['weight_kg']:.2f} kg {service} {fee:.2f}"
    )


def fee_table(parcels):
    """Return a mapping from parcel id to shipping fee."""
    if not isinstance(parcels, (list, tuple)):
        raise TypeError("parcels must be a list or tuple")
    return {
        parse_parcel(item)["id"]: shipping_fee(item) for item in parcels
    }

"""Batch parcel helpers."""

from decimal import Decimal

from .fees import shipping_fee
from .parcels import parse_many
from .rates import CENT


def batch_total(parcels):
    """Return the total shipping fee for several parcels."""
    parsed = parse_many(parcels)
    total = sum(
        (shipping_fee(item) for item in parcels),
        start=Decimal("0.00"),
    )
    return total.quantize(CENT)


def group_by_zone(parcels):
    """Return parcel ids grouped by shipping zone."""
    groups = {}
    for item in parse_many(parcels):
        groups.setdefault(item["zone"], []).append(item["id"])
    return groups


def heaviest_parcel(parcels):
    """Return the normalized parcel with the largest weight."""
    prepared = parse_many(parcels)
    if not prepared:
        raise ValueError("parcels must not be empty")
    return max(prepared, key=lambda item: item["weight_kg"])


def express_parcels(parcels):
    """Return only the parcels that use express service."""
    return [item for item in parse_many(parcels) if item["express"]]


def batch_summary(parcels):
    """Return a compact summary of a parcel batch."""
    prepared = parse_many(parcels)
    total = batch_total(parcels)
    return (
        f"{len(prepared)} parcels, "
        f"{len(express_parcels(parcels))} express, total {total:.2f}"
    )
